async function getJSON(url,opt,_parityRetry=false){const base=opt||{};const headers={'Accept-Language':String(state.uiLanguage||'en'),'X-KV30-UI-Language':String(state.uiLanguage||'en'),'X-KV30-Client':String(state.clientId||'web'),'X-KV30-State-Sync':'true',...(base.headers||{})};const method=String(base.method||'GET').toUpperCase();if(['POST','PUT','PATCH','DELETE'].includes(method)&&state.canonicalStateHash&&!headers['X-KV30-State-Hash'])headers['X-KV30-State-Hash']=state.canonicalStateHash;const r=await fetch(url,{cache:'no-store',credentials:'same-origin',...base,headers});const nextHash=r.headers?.get?.('X-KV30-State-Hash');if(nextHash)state.canonicalStateHash=nextHash;if(!r.ok){const e=await r.json().catch(()=>({}));const code=e.error||String(r.status);if(code==='stale_canonical_state'&&method!=='GET'&&!_parityRetry){state.canonicalStateHash=e.currentStateHash||null;await refreshCanonicalState();return getJSON(url,opt,true)}const err=new Error(code);err.code=code;err.details=e;err.userMessage=localizedApiMessage(e,code);if(code==='session_expired'){state.user=null;sessionStorage.clear();updateHeader?.();showToast(err.userMessage,'error');setTimeout(()=>{history.replaceState({},'',ROUTE_PATHS.home);render?.('home')},0)}if(code==='admin_session_expired'){localStorage.removeItem('kv.admin.role');showToast(err.userMessage,'error');setTimeout(()=>{history.replaceState({},'',ROUTE_PATHS.home);render?.('home')},0)}throw err}return r.json()}
const ROUTE_PATHS={home:'/',login:'/login',register:'/register',discover:'/discover',trending:'/trending',stories:'/stories',categories:'/categories',comic:'/comics',audio:'/audio',reel:'/reels',library:'/library',reader:'/reader',write:'/write',account:'/profile','reader-dashboard':'/reader-dashboard','author-dashboard':'/author-dashboard','admin-dashboard':'/admin-dashboard','ai-dashboard':'/ai-dashboard','account-settings':'/account-settings',settings:'/settings','phone-settings':'/phone-settings',help:'/help','safety-tickets':'/safety-tickets',editor:'/editor',series:'/series','media-tools':'/media-tools','payments':'/payments','notifications':'/notifications','messages':'/messages','subscriptions':'/subscriptions','reports':'/reports','ads':'/ads','stickers':'/stickers','admin-monetization':'/admin-monetization',analytics:'/analytics',audience:'/analytics/audience',performance:'/analytics/content',recommendations:'/recommendations',accessibility:'/settings/accessibility',privacy:'/settings/privacy',security:'/settings/security',interests:'/settings/interests','master-command':'/master-admin','security-audit':'/security-audit','regional-analytics':'/analytics/regional','events':'/events','creator-tiers':'/creator/tiers','my-writing':'/write'};
function currentRoute(){
  const p=location.pathname.replace(/\/$/,'')||'/';
  if(p==='/reg')return 'register';
  const byPath=Object.entries(ROUTE_PATHS).find(([,path])=>path===p);
  if(byPath)return byPath[0];
  const legacy=location.hash.replace(/^#/,'').trim();
  return legacy==='comics'?'comic':legacy==='stories'?'stories':legacy==='reels'?'reel':legacy||'home';
}
function navigate(route){
  const allowed=Object.keys(ROUTE_PATHS);
  const target=allowed.includes(route)?route:'home';
  history.pushState({},'',ROUTE_PATHS[target]);
  render(target);
}
function esc(v){return String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
state.user=null;state.myContent=[];state.authChecked=false;state.viewer=null;state.authMode='login';state.otpContext=null;state.resetContext=null;
function b64uFromBuffer(v){const b=new Uint8Array(v);let s='';for(const c of b)s+=String.fromCharCode(c);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function bufferFromB64u(s){const v=String(s||'').replace(/-/g,'+').replace(/_/g,'/');const p='='.repeat((4-v.length%4)%4);const raw=atob(v+p);return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function refreshCanonicalState(){const d=await getJSON('/api/state/canonical');state.canonicalStateHash=d.stateHash||state.canonicalStateHash;state.canonicalState=d.snapshot||null;return d}
