async function loginWithPasskey(){const out=document.getElementById('loginError');try{if(!window.PublicKeyCredential||!navigator.credentials){throw new Error(x('deviceAuthUnavailable'))}const opt=await getJSON('/api/auth/passkey/login/options',{method:'POST'});const cred=await navigator.credentials.get({publicKey:{challenge:bufferFromB64u(opt.challenge),rpId:opt.rpId,userVerification:'required',timeout:opt.timeout,allowCredentials:[]}});if(!cred)throw new Error('passkey_cancelled');const r=await getJSON('/api/auth/passkey/login/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge:opt.challenge,response:{clientDataJSON:b64uFromBuffer(cred.response.clientDataJSON),authenticatorData:b64uFromBuffer(cred.response.authenticatorData),signature:b64uFromBuffer(cred.response.signature),userHandle:b64uFromBuffer(cred.response.userHandle||new ArrayBuffer(0))}})});state.user=r.user;await loadCanonicalState();document.getElementById('login')?.close();updateHeader();render('home')}catch(e){if(out)out.textContent=uiErrorMessage(e)}}
async function registerPasskey(){try{if(!state.user)return openLogin();if(!window.PublicKeyCredential||!navigator.credentials)throw new Error(x('deviceAuthUnavailable'));const password=await uiPrompt(x('currentPasswordRequired'),true);if(!password)return;const opt=await getJSON('/api/auth/passkey/register/options',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});const cred=await navigator.credentials.create({publicKey:{challenge:bufferFromB64u(opt.challenge),rp:opt.rp,user:{id:bufferFromB64u(opt.user.id),name:opt.user.name,displayName:opt.user.displayName},pubKeyCredParams:opt.pubKeyCredParams,authenticatorSelection:opt.authenticatorSelection,timeout:opt.timeout,attestation:'none'}});if(!cred)throw new Error('passkey_cancelled');const r=await getJSON('/api/auth/passkey/register/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge:opt.challenge,response:{clientDataJSON:b64uFromBuffer(cred.response.clientDataJSON),attestationObject:b64uFromBuffer(cred.response.attestationObject)}})});showToast(r.passkey?.enabled?x('enableDeviceAuth'):x('passkeySetupCompleted'))}catch(e){showToast(uiErrorMessage(e))}}

