function publicProfilePage(){return page(x('profile'),`<div id="publicProfilePage" class="public-profile-page"><div class="kv30b-profile-skeleton card"><span class="skeleton-circle"></span><div class="skeleton-lines"><i></i><i></i><i></i></div></div></div>`)}
async function loadPublicProfile(){const uid=new URLSearchParams(location.search).get('userId');const box=document.getElementById('publicProfilePage');if(!box||!uid)return;if(state.user&&uid===state.user.id){navigate('account');return}try{const d=await getJSON('/api/profile/public?userId='+encodeURIComponent(uid));const p=d.profile||{};const avatar=p.profilePhoto?`<img class="profile-avatar-large" src="${esc(p.profilePhoto)}" alt="${esc(p.username)}">`:`<div class="profile-avatar-large avatar-fallback">${esc((p.name||p.username||'U').slice(0,1).toUpperCase())}</div>`;const actions=p.id!=='system'?(state.user?`<button type="button" class="primary" id="publicProfileFollow">${d.following?'✓ '+x('following'):'＋ '+x('followAuthor')}</button><button type="button" class="button" id="publicProfileSubscribe">${d.subscribed?'✓ '+x('authorSubscribed'):x('authorSubscription')}</button>${d.canMessage?`<button type="button" class="button" id="publicProfileMessage">${kvIcon('message')} ${x('message')}</button>`:''}`:`<button type="button" class="primary" data-open-login>${t('login')} · ${x('followAuthor')}</button>`):'';box.innerHTML=`<section class="profile-dashboard card public-profile-card"><div class="profile-top">${avatar}<div class="profile-main"><span class="eyebrow">${x('profile')}</span><h1>${esc(p.name||p.username)}</h1><p class="muted">@${esc(p.username)} · ${esc(p.role||x('userRole'))}${p.verified?' · ✓ '+x('verifiedLabel'):''}</p><p>${esc(p.bio||'')}</p></div><div class="button-row profile-actions">${actions}</div></div><div class="profile-stats"><div><strong>${Number(p.followers||0).toLocaleString()}</strong><span>${x('followers')}</span></div><div><strong>${Number(p.following||0).toLocaleString()}</strong><span>${x('following')}</span></div><div><strong>${(d.works||[]).length}</strong><span>${x('myWorks')}</span></div></div></section><section class="section-block"><div class="section-heading"><div><span class="eyebrow">${x('myWorks')}</span><h2>${x('myWorks')}</h2></div></div><div id="publicProfileWorks" class="content-grid"></div></section>`;const w=document.getElementById('publicProfileWorks');if(w)w.innerHTML=(d.works||[]).map(contentCard).join('')||`<div class="empty card">${x('noPublicWorksYet')}</div>`;bindContentButtons();box.querySelectorAll('[data-open-login]').forEach(b=>b.onclick=openLogin);const fb=document.getElementById('publicProfileFollow');if(fb)fb.onclick=async()=>{try{const r=await getJSON('/api/follows',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({authorId:p.id,following:!d.following})});d.following=r.following;fb.textContent=d.following?'✓ '+x('following'):'＋ '+x('followAuthor')}catch(e){showToast(uiErrorMessage(e),'error')}};const sb=document.getElementById('publicProfileSubscribe');if(sb)sb.onclick=()=>{if(d.subscribed){showToast(x('authorSubscriptionAlreadyActiveMessage'));return}if(!state.user){openLogin();return}state.pendingSubscriptionPlan='author_subscription';state.pendingAuthorId=p.id;navigate('payments')};const mb=document.getElementById('publicProfileMessage');if(mb)mb.onclick=()=>navigate('messages');}catch(e){box.innerHTML=`<div class="card error"><h2>${x('profileUnavailable')}</h2><p>${esc(uiErrorMessage(e)||x('unableToLoadProfile'))}</p></div>`}}

function changePasswordCard(){return `<article class="card"><h2>${kvIcon('lock')}${x('changePassword')}</h2><p class="muted">${x('oldPassword')} → ${x('newPassword')} → ${x('confirmNewPassword')}</p><form id="changePasswordForm" class="profile-form"><label>${x('username')}<input value="${esc(state.user?.userId||'')}" disabled></label><label>${x('oldPassword')}<div class="password-field"><input id="oldPassword" type="password" autocomplete="current-password" required><button type="button" class="button password-toggle" data-toggle-password="oldPassword">${x('showPassword')}</button></div></label><label>${x('newPassword')}<div class="password-field"><input id="newPassword" type="password" autocomplete="new-password" required><button type="button" class="button password-toggle" data-toggle-password="newPassword">${x('showPassword')}</button></div></label><label>${x('confirmNewPassword')}<div class="password-field"><input id="confirmNewPassword" type="password" autocomplete="new-password" required><button type="button" class="button password-toggle" data-toggle-password="confirmNewPassword">${x('showPassword')}</button></div></label><button class="primary" type="submit">${x('changePassword')}</button><div id="changePasswordStatus" class="result"></div></form></article>`}
function royaltyDetailsCard(){const locked=!!state.royaltyDetailsVerified;return `<article class="card"><h2>${kvIcon('coins')}${x('royaltyDetails')}</h2><p class="muted">${locked?x('royaltyLocked'):'Add your royalty/payment details. The mobile number entered here receives the verification OTP.'}</p>${locked?`<div id="royaltyLockedDetails" class="result">${x('ui_verified_details_are_on_file')}</div><button type="button" class="button" id="royaltyChangeRequest">${x('ui_request_change_approval')}</button><div id="royaltyStatus" class="result"></div>`:`<form id="royaltyDetailsForm" class="profile-form"><label>${x('bankAccountNumber')}<input id="royaltyBankAccount" inputmode="numeric" required></label><label>${x('bankName')}<input id="royaltyBankName" required></label><label>${x('ifsc')}<input id="royaltyIfsc" required></label><label>${x('bankBranch')}<input id="royaltyBranch" required></label><label>${x('panNumber')}<input id="royaltyPan" required></label><label>${x('royaltyEmail')}<input id="royaltyEmail" type="email" required></label><label>${x('royaltyMobile')}<input id="royaltyMobile" inputmode="tel" required></label><button class="primary" type="submit">${x('verifyAndSave')}</button><div id="royaltyStatus" class="result"></div></form>`}</article>`}
async function initAccountSecurity(){try{const rd=await getJSON('/api/profile/royalty-details');state.royaltyDetailsVerified=!!rd.verified}catch(e){state.royaltyDetailsVerified=false}document.querySelectorAll('[data-toggle-password]').forEach(b=>b.onclick=()=>{const input=document.getElementById(b.dataset.togglePassword);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?x('hidePassword'):x('showPassword')});document.getElementById('royaltyChangeRequest')?.addEventListener('click',async()=>{const out=document.getElementById('royaltyStatus');try{const r=await getJSON('/api/profile/royalty-details/change-request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({})});out.textContent=x('ticketSentForApproval').replace('{v1}',r.ticket?.id||'')}catch(e){out.textContent=uiErrorMessage(e)}});const f=document.getElementById('changePasswordForm');if(f)f.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('changePasswordStatus');try{const r=await getJSON('/api/auth/change-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({oldPassword:document.getElementById('oldPassword').value,newPassword:document.getElementById('newPassword').value,confirmPassword:document.getElementById('confirmNewPassword').value})});out.textContent=r.message||x('passwordChanged');f.reset()}catch(err){out.textContent=humanAuthError(err.code||err.message)}};const rf=document.getElementById('royaltyDetailsForm');if(rf)rf.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('royaltyStatus');try{const r=await getJSON('/api/profile/royalty-details',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bankAccountNumber:document.getElementById('royaltyBankAccount').value,bankName:document.getElementById('royaltyBankName').value,ifsc:document.getElementById('royaltyIfsc').value,bankBranch:document.getElementById('royaltyBranch').value,pan:document.getElementById('royaltyPan').value,email:document.getElementById('royaltyEmail').value,mobile:document.getElementById('royaltyMobile').value})});const m=await openOtpDialog({target:r.target,purpose:r.purpose,sendPath:'/api/auth/resend-otp',sendBody:{target:r.target,purpose:r.purpose},message:x('otpSent'),lastResponse:r});if(!m)return;out.textContent=m.verified?x('verifiedAndLocked'):x('royaltyLocked')}catch(err){out.textContent=humanAuthError(err.code||err.message)}}}
function account(){if(!state.user)return page(t('account'),loginGate());queueMicrotask(loadProfileProgressReport);const avatar=state.user.profilePhoto?`<img class="profile-avatar-large" src="${esc(state.user.profilePhoto)}" alt="${esc(state.user.username)}">`:`<div class="profile-avatar-large avatar-fallback">${esc((state.user.name||state.user.username||'U').slice(0,1).toUpperCase())}</div>`;return page(x('profile'),`${adStrip('profile')}<section class="profile-dashboard card"><div class="profile-top">${avatar}<div class="profile-main"><span class="eyebrow">${x('profile')}</span><h1>${esc(state.user.name||state.user.username)}</h1><p class="muted">@${esc(state.user.username)}</p><p>${x('privacyNote')}</p></div><div class="button-row">${routeLink('settings',x('settings'),'button')}<button type="button" class="button" id="enablePasskey">${x('enableDeviceAuth')}</button>${routeLink('write',x('myWriting'),'primary button')}</div></div><div class="profile-stats"><div><strong>${state.user.followers||0}</strong><span>${x('followers')}</span></div><div><strong>${state.user.following||0}</strong><span>${x('following')}</span></div><div><strong>${state.myContent?.length||0}</strong><span>${x('myWorks')}</span></div></div></section><section class="card" id="profileProgressReport"><strong>${x('progressReport')}</strong><p class="muted">${x('loading')}</p></section><div class="tabs profile-tabs" role="tablist"><button type="button" class="tab active" data-profile-tab="works" aria-selected="true">${x('myWorks')}</button><button type="button" class="tab" data-profile-tab="posts" aria-selected="false">${x('posts')}</button><button type="button" class="tab" data-profile-tab="updates" aria-selected="false">${x('updates')}</button></div><div id="profileTabPanel" class="profile-tab-panel card"><strong>${x('myWorks')}</strong><p class="muted">${t('writeText')}</p>${routeLink('write',x('open'),'button')}</div><div class="grid"><article class="card"><h2>${kvIcon('write')}${x('myWorks')}</h2><p>${t('writeText')}</p>${routeLink('write',x('open'),'button')}</article><article class="card"><h2>${kvIcon('spark')}${x('subscription')}</h2><div class="subscription-list">${subscriptionRow('comicReader',x('comicReader'))}${subscriptionRow('audioReader',x('audioReader'))}${subscriptionRow('reelReader',x('reelReader'))}</div></article><article class="card"><h2>${kvIcon('coins')}${x('earnings')}</h2><p>${x('followers')}: ${state.user.followers||0}</p></article><article class="card"><h2>${kvIcon('lock')}${x('privateProfile')}</h2><p><strong>${x('mobile')}:</strong> <span id="profileMobile"></span></p><p><strong>${x('email')}:</strong> <span id="profileEmail"></span></p><p><strong>${x('verified')}:</strong> <span id="verificationState"></span></p></article></div><section class="card"><div class="section-heading"><h2>${x('profileSettings')}</h2>${routeLink('settings',x('settings'),'button')}</div><form id="profileForm" class="profile-form"><label>${x('username')}<input value="${esc(state.user.username)}" disabled></label><label>${x('name')}<input id="profileName"></label><label>${x('location')}<input id="profileLocation"></label><label>${x('address')}<input id="profileAddress"></label><label>${x('dob')}<input id="profileDob" type="date"></label><label>${x('gender')}<input id="profileGender"></label><label>${x('profilePhoto')}<input id="profilePhoto" placeholder="${x('ui_https')}"></label><button class="primary" type="submit">${x('saveProfile')}</button></form><div id="profileStatus" class="result"></div></section>${changePasswordCard()}${royaltyDetailsCard()}${state.user.locked?`<div class="notice">${x('accountLocked').replace('{v1}',esc(state.user.appealStatus||''))}<textarea id="apology" placeholder="${x('ui_apology_appeal')}"></textarea><button class="primary" data-appeal>${x('ui_submit_appeal')}</button></div>`:''}<button class="link-button" data-logout>${x('logout')}</button>`)}
