async function initInterests(){const box=document.getElementById('interestChoices');if(!box)return;try{const d=await getJSON('/api/preferences/interests');const set=new Set(d.interests||[]);box.querySelectorAll('[data-interest]').forEach(b=>b.classList.toggle('active',set.has(b.dataset.interest)));box.querySelectorAll('[data-interest]').forEach(b=>b.onclick=()=>b.classList.toggle('active'));document.getElementById('saveInterests').onclick=async()=>{const interests=[...box.querySelectorAll('[data-interest].active')].map(b=>b.dataset.interest);const r=await getJSON('/api/preferences/interests',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({interests})});document.getElementById('interestStatus').textContent=x('savedInterests').replace('{v1}',String(r.interests.length))}}catch(e){document.getElementById('interestStatus').textContent=uiErrorMessage(e)}}
async function loadMasterCommand(){
 const b=document.getElementById('masterCommand');if(!b)return;
 try{
  const [d,m,lr]=await Promise.all([getJSON('/api/admin/command-center'),getJSON('/api/admin/command-center/matrix'),getJSON('/api/language-registry')]);
  const events=(d.telemetry.latest||[]).map(e=>`<div class="kv30b-telemetry-row"><span><b>${esc(e.action||x('eventLabel'))}</b><small>${esc(e.actor||x('systemLabel'))} · ${esc(e.resourceType||'')}</small></span><span class="kv30b-state">${esc(e.result||x('recorded'))}</span></div>`).join('')||'<div class="kv30b-empty">'+x('ui_no_telemetry_events_recorded')+'</div>';
  const langs=(m.languages.rows||[]).map(l=>`<span class="kv30b-chip"><b>${esc(l.code)}</b> ${esc(l.name)}</span>`).join('');
  const aiRows=(m.ais.rows||[]).map(x=>`<tr><td><code>${esc(x.id)}</code></td><td>${esc(x.tier)}</td><td>${esc(x.responsibility)}</td><td>${esc((x.pipeline||[]).join(' · '))}</td><td>${x.active?x('passStatus'):x('reviewStatus')}</td></tr>`).join('');
  const futureRows=(lr.languages||[]).filter(row=>row.source!=='canonical').map(row=>`<div class="language-governance-row"><span><b>${esc(row.code)}</b> ${esc(row.nativeName||row.name)}</span><span class="pill">${esc(row.status||x('proposed'))}</span></div>`).join('')||'<p class="muted">'+x('ui_no_staged_future_languages')+'</p>';
  b.innerHTML=`<article class="kv30b-card kv30b-span-2"><div class="kv30b-card-head"><div><span class="kv30b-code">${x('ui_system_audit')}</span><h3>${x('ui_live_verification_plane')}</h3></div><span class="kv30b-status kv30b-status-pass">● ${x('internalLedger')}</span></div><div class="kv30b-metrics"><div><strong>${d.telemetry.events}</strong><span>${x('ui_audit_events')}</span></div><div><strong>${m.ais.count}</strong><span>${x('ui_registered_ais')}</span></div><div><strong>${m.languages.count}</strong><span>${x('ui_contract_languages')}</span></div><div><strong>${d.ai.active}</strong><span>${x('ui_active_ais')}</span></div></div></article><article class="kv30b-card kv30b-span-2"><div class="kv30b-card-head"><div><span class="kv30b-code">${x('ui_part_3_current_registry_data')}</span><h3>${x('ui_language_model_pipeline_matrix')}</h3><small>${x('ui_source_current_internal_ai_and_language_registries')}</small></div><span class="kv30b-status kv30b-status-pass">● ${x('aiCountLang').replace('{v1}',String(m.ais.count)).replace('{v2}',String(m.languages.count))}</span></div><div class="kv30b-chip-grid">${langs}</div><div class="kv30b-table-wrap"><table class="kv30b-table"><thead><tr><th>${x('internalAi')}</th><th>${x('ui_tier')}</th><th>${x('ui_responsibility')}</th><th>${x('ui_pipeline')}</th><th>${x('ui_state')}</th></tr></thead><tbody>${aiRows}</tbody></table></div></article><article class="kv30b-card kv30b-span-2 language-governance-card"><div class="kv30b-card-head"><div><span class="kv30b-code">${x('ui_governed_localization')}</span><h3>${x('ui_new_language_lifecycle')}</h3><small>${x('languageRegistryRule')}</small></div><span class="kv30b-status ${lr.enabledCount>=23?'kv30b-status-pass':'kv30b-status-critical'}">● ${lr.enabledCount} ${x('enabledRequiredStatus')}</span></div><div class="language-governance-grid"><label>${x('ui_code')}<input id="newLanguageCode" maxlength="7" placeholder="${x('ui_e_g_kok_xx')}"></label><label>${x('ui_english_name')}<input id="newLanguageName" maxlength="80" placeholder="${x('ui_language_name')}"></label><label>${x('ui_native_name')}<input id="newLanguageNativeName" maxlength="120" placeholder="${x('ui_native_name')}"></label><label>${x('ui_iso_639_3')}<input id="newLanguageIso3" maxlength="3" placeholder="${x('ui_abc')}"></label></div><div class="button-row"><button type="button" class="primary" id="proposeLanguage">${x('ui_stage_language')}</button><button type="button" class="button" id="refreshLanguageGovernance">${x('ui_refresh')}</button></div><div class="language-governance-evidence"><label><input type="checkbox" id="languageUiCoverage">${x('ui_ui_strings_reviewed')}</label><label><input type="checkbox" id="languageAiCoverage">${x('ui_ai_contract_runtime_reviewed')}</label><label><input type="checkbox" id="languageTtsCoverage">${x('ui_tts_coverage_verified')}</label><label><input type="checkbox" id="languageTestCoverage">${x('ui_deterministic_tests_added_passed')}</label><label><input type="checkbox" id="languageGovernanceReview">${x('ui_governance_review_complete')}</label></div><div class="button-row"><button type="button" class="button" id="recordLanguageEvidence">${x('ui_record_evidence')}</button><button type="button" class="button" id="approveLanguage">${x('ui_approve')}</button><button type="button" class="primary" id="enableLanguage">${x('ui_enable')}</button></div><div id="languageGovernanceRows">${futureRows}</div><p id="languageGovernanceResult" class="muted" aria-live="polite"></p></article><article class="kv30b-card"><div class="kv30b-card-head"><div><span class="kv30b-code">${x('ui_finance')}</span><h3>${x('ui_ledger')}</h3></div></div><div class="kv30b-list"><div><span>${x('coinsInBalances')}</span><b>${d.financial.coins}</b></div><div><span>${x('ui_ledger_transactions')}</span><b>${d.financial.transactions}</b></div><div><span>${x('ui_subscription_payments')}</span><b>${d.financial.subscriptions}</b></div></div></article><article class="kv30b-card"><div class="kv30b-card-head"><div><span class="kv30b-code">${x('ui_risk_gates')}</span><h3>${x('ui_critical_alerts')}</h3></div><span class="kv30b-status ${d.alerts.lockedUsers||d.alerts.openTickets||d.alerts.pendingModeration?'kv30b-status-critical':'kv30b-status-pass'}">${d.alerts.lockedUsers||d.alerts.openTickets||d.alerts.pendingModeration?'● '+x('reviewStatus'):'● '+x('clearStatus')}</span></div><div class="kv30b-list"><div><span>${x('ui_locked_accounts')}</span><b>${d.alerts.lockedUsers}</b></div><div><span>${x('ui_open_tickets')}</span><b>${d.alerts.openTickets}</b></div><div><span>${x('ui_pending_moderation')}</span><b>${d.alerts.pendingModeration}</b></div></div></article><article class="kv30b-card kv30b-span-2"><div class="kv30b-card-head"><div><span class="kv30b-code">${x('ui_telemetry_last_20')}</span><h3>${x('ui_audit_stream')}</h3></div><button class="button" data-route="security-audit">${x('ui_inspect_trace')}</button></div><div class="kv30b-telemetry">${events}</div></article>`;
  const code=()=>String(document.getElementById('newLanguageCode')?.value||'').trim().toLowerCase();
  const result=document.getElementById('languageGovernanceResult');
  document.getElementById('proposeLanguage')?.addEventListener('click',async()=>{try{const row=await getJSON('/api/admin/languages/propose',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:code(),name:document.getElementById('newLanguageName')?.value,nativeName:document.getElementById('newLanguageNativeName')?.value,iso639_3:document.getElementById('newLanguageIso3')?.value})});result.textContent=x('languageStaged').replace('{v1}',String(row.language.code));loadMasterCommand()}catch(e){result.textContent=uiErrorMessage(e)||x('languageProposalFailed')}});
  document.getElementById('recordLanguageEvidence')?.addEventListener('click',async()=>{try{const row=await getJSON(`/api/admin/languages/${encodeURIComponent(code())}/evidence`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({evidence:{uiCoverage:document.getElementById('languageUiCoverage')?.checked===true,aiCoverage:document.getElementById('languageAiCoverage')?.checked===true,ttsCoverage:document.getElementById('languageTtsCoverage')?.checked===true,testCoverage:document.getElementById('languageTestCoverage')?.checked===true,governanceReview:document.getElementById('languageGovernanceReview')?.checked===true}})});result.textContent=x('languageEvidenceRecorded').replace('{v1}',String(row.language.code)).replace('{v2}',String(row.language.status));loadMasterCommand()}catch(e){result.textContent=uiErrorMessage(e)||x('evidenceUpdateFailed')}});
  document.getElementById('approveLanguage')?.addEventListener('click',async()=>{try{const row=await getJSON(`/api/admin/languages/${encodeURIComponent(code())}/approve`,{method:'POST'});result.textContent=x('languageApproved').replace('{v1}',String(row.language.code));loadMasterCommand()}catch(e){result.textContent=uiErrorMessage(e)||x('approvalBlockedEvidence')}});
  document.getElementById('enableLanguage')?.addEventListener('click',async()=>{try{const row=await getJSON(`/api/admin/languages/${encodeURIComponent(code())}/enable`,{method:'POST'});result.textContent=x('languageEnabled').replace('{v1}',String(row.language.code));loadMasterCommand()}catch(e){result.textContent=uiErrorMessage(e)||x('enableBlockedApproval')}});
  document.getElementById('refreshLanguageGovernance')?.addEventListener('click',loadMasterCommand);
 }catch(e){b.innerHTML=`<div class="kv30b-card kv30b-error">${esc(uiErrorMessage(e))}</div>`}
}
async function loadSecurityAudit(){const form=document.getElementById('securityAiForm'),out=document.getElementById('securityAiResult');if(form&&out)form.onsubmit=async e=>{e.preventDefault();out.textContent=x('ui_security_ai_is_analysing');try{const r=await getJSON('/api/admin/ai/security-defense',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:document.getElementById('securityAiInput').value})});out.textContent=`${x('riskLabel')}: ${r.assessment.risk} · ${x('actionLabel')}: ${r.assessment.action} · ${x('signalsLabel')}: ${(r.assessment.signals||[]).join(', ')||x('none')}`;}catch(err){out.textContent=humanAuthError(err.code||err.message)}};const b=document.getElementById('securityAudit');if(!b)return;try{const d=await getJSON('/api/admin/security-audit');b.innerHTML=(d.events||[]).slice(0,100).map(e=>`<div class="service-row"><span><strong>${esc(e.action||x('eventLabel'))}</strong><small>${esc(e.actor||x('systemLabel'))} · ${esc(e.resourceType||'')}</small></span><span>${esc(e.result||'')}</span></div>`).join('')||'<p class="muted">'+x('ui_no_audit_events_yet')+'</p>'}catch(e){b.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
