function securityPage(){if(!state.user)return loginGate();return page(x('accountSecurity'),`<section class="card"><span class="eyebrow">${x('ui_account')}</span><h1>${kvIcon('lock')} ${x('accountSecurity')}</h1><p>${x('sessionLogoutPolicy')}</p><div class="button-row">${routeLink('account-settings',x('changePassword'),'button')}<button type="button" class="danger button" id="logoutAllDevices">${x('logoutOtherSessions')}</button></div><div id="securityStatus" class="result"></div></section>`)}
async function loadAnalyticsOverview(){const b=document.getElementById('analyticsOverview');if(!b)return;try{const d=await getJSON('/api/analytics/overview');b.innerHTML=`<article class="card"><h3>${x('overview30Day')}</h3><div class="stats-grid"><div><strong>${Number(d.summary.views).toLocaleString()}</strong><span>${x('viewsLabel')}</span></div><div><strong>${Number(d.summary.likes).toLocaleString()}</strong><span>${x('likesLabel')}</span></div><div><strong>${Number(d.summary.comments).toLocaleString()}</strong><span>${x('comments')}</span></div><div><strong>${Number(d.summary.followers).toLocaleString()}</strong><span>${x('followersLabel')}</span></div></div></article><article class="card"><h3>${x('topPerformingContent')}</h3>${d.topContent.map(c=>`<div class="service-row"><span><strong>${esc(c.title)}</strong><small>${esc(c.type)} · ${esc(c.workType||'')}</small></span><span>${x('viewCountLabel').replace('{v1}',Number(c.views).toLocaleString())}</span></div>`).join('')||'<p class="muted">'+x('ui_no_creator_content_yet')+'</p>'}</article><article class="card"><h3>${x('formatMix')}</h3><div class="chips">${Object.entries(d.summary.byType).map(([k,v])=>`<span class="pill">${esc(k)}: ${v}</span>`).join('')}</div></article>`}catch(e){b.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
async function loadAudienceInsights(){const b=document.getElementById('audienceInsights');if(!b)return;try{const d=await getJSON('/api/analytics/audience');const peak=Object.entries(d.activeHours).sort((a,b)=>b[1]-a[1]).slice(0,5).filter(x=>x[1]>0);b.innerHTML=`<article class="card"><h3>${x('followersLabel')}</h3><strong>${Number(d.followers).toLocaleString()}</strong></article><article class="card"><h3>${x('activeHours')}</h3>${peak.length?peak.map(([h,v])=>`<div class="service-row"><span>${String(h).padStart(2,'0')}:00</span><strong>${v}</strong></div>`).join(''):'<p class="muted">'+x('ui_activity_history_will_appear_as_real_events_are_collected')+'</p>'}</article><article class="card"><h3>${x('ui_demographics')}</h3><p class="muted">${x('ui_gender_age_and_location_are_not_collected_in_this_analytics_layer_so_n')}</p></article>`}catch(e){b.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
async function loadPerformance(){const b=document.getElementById('contentPerformance'),sel=document.getElementById('performanceSelector');if(!b||!sel)return;try{const mine=await getJSON('/api/my-content');const works=mine.content||[];sel.innerHTML=`<label>${x('selectWork')}<select id="performanceWork">${works.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('')}</select></label>`;const load=async()=>{const selected=document.getElementById('performanceWork').value;if(!selected){b.innerHTML='<div class="card">'+x('ui_no_creator_content_yet')+'</div>';return}const d=await getJSON('/api/analytics/content-performance?contentId='+encodeURIComponent(selected));if(!d.content){b.innerHTML='<div class="card">'+x('ui_no_creator_content_yet')+'</div>';return}b.innerHTML=`<article class="card"><h3>${esc(d.content.title)}</h3><div class="stats-grid"><div><strong>${d.content.views}</strong><span>${x('viewsLabel')}</span></div><div><strong>${d.content.likes}</strong><span>${x('likesLabel')}</span></div><div><strong>${d.content.comments}</strong><span>${x('comments')}</span></div><div><strong>${d.content.rating.toFixed(2)}</strong><span>${x('rating')}</span></div></div></article><article class="card"><h3>${x('chapterBreakdown')}</h3>${d.parts.map(p=>`<div class="service-row"><span>${p.partNumber}. ${esc(p.title)}</span><span>${p.views} views · ${p.likes} likes</span></div>`).join('')||'<p class="muted">'+x('ui_no_series_parts_available')+'</p>'}</article>`};document.getElementById('performanceWork').onchange=load;await load()}catch(e){b.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
async function loadRecommendations(){const b=document.getElementById('recommendationGrid');if(!b)return;try{const d=await getJSON('/api/recommendations');b.innerHTML=(d.recommendations||[]).map(contentCard).join('')||'<div class="empty card">'+x('ui_no_recommendations_yet_explore_discover_to_build_more_history')+'</div>';bindContentButtons()}catch(e){b.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
async function initAccessibility(){const form=document.getElementById('accessibilityForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('accessibilityStatus');try{const r=await getJSON('/api/preferences/accessibility',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({textSize:document.getElementById('a11yTextSize').value,contrast:document.getElementById('a11yContrast').value,reduceMotion:document.getElementById('a11yReduceMotion').checked,captions:document.getElementById('a11yCaptions').checked})});out.textContent=r.message||x('accessibilitySettingsSaved')}catch(e){out.textContent=uiErrorMessage(e)}}}
async function initPrivacy(){const form=document.getElementById('privacyForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('privacyStatus');try{const r=await getJSON('/api/preferences/privacy',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({profileVisibility:document.getElementById('privacyProfile').value,personalization:document.getElementById('privacyPersonalization').checked,analytics:document.getElementById('privacyAnalytics').checked})});out.textContent=r.message||x('privacySettingsSaved')}catch(e){out.textContent=uiErrorMessage(e)}}}
async function initSecurity(){document.getElementById('logoutAllDevices')?.addEventListener('click',async()=>{const out=document.getElementById('securityStatus');try{const r=await getJSON('/api/auth/logout-all',{method:'POST'});out.textContent=r.message||x('otherSessionsInvalidated')}catch(e){out.textContent=uiErrorMessage(e)}})}
function subscriptionRow(k,label){return `<div class="service-row"><span>${label}</span><span class="pill">${state.user.subscriptions[k]?x('active'):x('available')}</span>${routeLink('subscriptions',x('manage'),'button')}</div>`}
function help(){const loggedIn=!!state.user;return page(t('help'),loggedIn?`<section class="help-support-shell"><article class="card"><h1>${kvIcon('help')}${x('supportTitle')}</h1><p>${x('supportThreeLayers')}</p><div class="notice">${x('supportNote')}</div><article class="card ai-help-panel"><div class="section-heading"><div><span class="eyebrow">${x('supportAi')}</span><h2>${x('supportThreeLayers')}</h2></div><span class="service-badge">${x('ui_ai_layer_on')}</span></div><form id="helpAiForm"><label>${x('askInternalAi')}<textarea id="helpAiQuestion" rows=4 maxlength=5000 required placeholder="${x('ui_describe_the_software_design_security_or_help_problem')}"></textarea></label><button type="submit" class="primary">${x('askInternalAi')}</button></form><div id="helpAiResult" class="result"></div></article><div id="helpContactSummary" class="support-contact-summary muted">${x('supportContact')}…</div><form id="helpSupportForm"><label>${x('supportChannel')}<select id="helpChannel"><option value="ai">${x('supportAi')}</option><option value="email">${x('supportEmail')}</option><option value="mobile">${x('supportMobile')}</option></select></label><label>${x('supportProblem')}<textarea id="helpProblem" rows="6" maxlength="5000" required></textarea></label><label>${x('screenshotOptional')}<input id="helpScreenshot" type="file" accept="image/png,image/jpeg,image/webp"></label><button type="submit" class="primary">${x('supportCreate')}</button><div id="helpStatus" class="result"></div></form><p class="muted">${x('supportWriterScope')}</p><p class="muted">${x('supportCritical')}</p></article><article class="card"><h2>${kvIcon('history')} ${x('supportHistory')}</h2><div id="helpTicketHistory" class="writing-list"><p class="muted">${x('supportNoTickets')}</p></div></article><article class="card"><h2>${kvIcon('shield')} ${x('moderation')}</h2><p>${x('aiReview')}. ${x('uncertainCases')}</p></article><article class="card"><h2>${kvIcon('document')} ${x('policyTitle')}</h2><p>${x('policyText')}</p></article><article class="card"><h2>${kvIcon('lock')} ${x('privacyTitle')}</h2><p>${x('privacyNote')}</p></article></section>`:`<section class="help-support-shell"><article class="card ai-help-public"><div class="section-heading"><div><span class="eyebrow">${x('supportAi')}</span><h1>${kvIcon('spark')} ${x('helpLoginTitle')}</h1></div><span class="service-badge">${x('internalLayerOn')}</span></div><p>${x('helpLoginText')}</p><form id="publicAiHelpForm"><label>${x('ui_ask_about_login_otp_registration_or_password')}<input id="publicAiHelpQuestion" maxlength="800" required placeholder="${x('ui_e_g_i_did_not_receive_my_otp')}"></label><button class="primary" type="submit">${x('askInternalAi')}</button></form><div id="publicAiHelpAnswer" class="result"></div><div class="button-row"><button class="primary" data-open-login>${x('helpLoginAction')}</button><button class="button" data-register>${x('helpRegisterAction')}</button></div><p class="muted">${x('helpForgotText')}</p><div class="notice">${x('helpVerifiedContact')}</div></article><article class="card"><h2>${kvIcon('ticket')} ${x('supportCreate')}</h2><p class="muted">${x('ui_public_help_covers_account_creation_otp_verification_failure_otp_not_r')}</p><form id="publicHelpTicketForm"><label>${x('ui_registered_email_mobile')}<input id="publicHelpTicketIdentifier" required></label><label>${x('supportProblem')}<textarea id="publicHelpTicketProblem" rows="5" maxlength="5000" required></textarea></label><label>${x('screenshotOptional')}<input id="publicHelpTicketScreenshot" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="primary" type="submit">${x('supportCreate')}</button><div id="publicHelpTicketResult" class="result"></div></form><hr><form id="publicHelpTicketCommentForm"><label>${x('ui_track_ticket_number')}<input id="publicHelpTicketCommentNumber" required></label><label>${x('ui_registered_email_mobile')}<input id="publicHelpTicketCommentIdentifier" required></label><label>${x('comment')}<textarea id="publicHelpTicketComment" rows="4" maxlength="5000" required></textarea></label><button class="button" type="submit">${x('comment')}</button><div id="publicHelpTicketCommentResult" class="result"></div></form></article><article class="card"><h2>❓ ${t('help')}</h2><p>${t('helpText')}</p><p class="muted">${x('ui_public_help_covers_account_creation_otp_verification_failure_otp_not_r')}</p><form id="publicAccountStateForm"><label>${x('ui_registered_email_mobile')}<input id="publicAccountIdentifier" required></label><label>${x('ui_request_type')}<select id="publicAccountStateType"><option value="unblock">${x('ui_unblock_blocked_account')}</option><option value="reactivate">${x('ui_reactivate_deactivated_account')}</option><option value="deletion">${x('ui_request_account_deletion')}</option></select></label><label>${x('ui_reason')}<textarea id="publicAccountStateReason" rows="4" maxlength="3000" required></textarea></label><label>${x('screenshotOptional')}<input id="publicAccountStateScreenshot" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="primary" type="submit">${x('ui_submit_to_master_admin')}</button><div id="publicAccountStateResult" class="result"></div></form><hr><form id="publicTicketTrackForm"><label>${x('ui_track_ticket_number')}<input id="publicTicketNumber" required></label><label>${x('ui_registered_email_mobile')}<input id="publicTicketIdentifier" required></label><button class="button" type="submit">${x('ui_track_ticket')}</button><div id="publicTicketTrackResult" class="result"></div></form></article></section>`)}
async function initHelpSupport(){const form=document.getElementById('helpSupportForm'),status=document.getElementById('helpStatus');if(!form)return;const aiForm=document.getElementById('helpAiForm'),aiOut=document.getElementById('helpAiResult');if(aiForm&&aiOut)aiForm.onsubmit=async e=>{e.preventDefault();const q=document.getElementById('helpAiQuestion').value.trim();if(!q)return;aiOut.textContent=x('ui_internal_ai_is_analysing');try{const r=await getJSON('/api/ai/help',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({problem:q,language:state.uiLanguage})});aiOut.innerHTML=`<strong>${esc(r.ai.reply||'')}</strong><p class="muted">${esc(r.ai.category||'general')} · ${Math.round(Number(r.ai.confidence||0)*100)}% · ${r.ai.ticketId?`${x('ticketLabel')} ${esc(r.ai.ticketId)}`:x('noTicketRequired')}</p>`}catch(e){aiOut.textContent=uiErrorMessage(e)}};try{const ctx=await getJSON('/api/help/context');const summary=document.getElementById('helpContactSummary');if(summary)summary.textContent=`${x('supportContact')}: ${ctx.verifiedContact} (${ctx.verifiedContactType})`;const email=document.querySelector('#helpChannel option[value="email"]'),mobile=document.querySelector('#helpChannel option[value="mobile"]');if(email)email.disabled=!ctx.channels.email;if(mobile)mobile.disabled=!ctx.channels.mobile;form.onsubmit=async e=>{e.preventDefault();try{const r=await getJSON('/api/help/tickets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:document.getElementById('helpChannel').value,problem:document.getElementById('helpProblem').value,screenshot:await fileAsDataUrl(document.getElementById('helpScreenshot'))})});const ticket=r.ticket;status.innerHTML=`<strong>${x('supportResult')}</strong><br>${esc(r.ai.reply||'')}<br><strong>${x('supportTicketId')}:</strong> ${esc(ticket.id)}<br>${ticket.status==='ai_resolved'?x('supportAiSolved'):(ticket.assignedQueue==='master_admin'?x('supportRoutedMaster'):x('supportRoutedAdmin'))}`;document.getElementById('helpProblem').value='';await loadHelpTickets()}catch(e){status.textContent=uiErrorMessage(e)}};await loadHelpTickets()}catch(e){if(status)status.textContent=uiErrorMessage(e)}}
async function loadHelpTickets(){const box=document.getElementById('helpTicketHistory');if(!box||!state.user)return;try{const r=await getJSON('/api/help/tickets');box.innerHTML=r.tickets.length?r.tickets.map(t=>`<article class="writing-item"><div><strong>${esc(t.id)}</strong><div class="muted">${esc(t.status)} · ${esc(t.category)}</div><div>${esc(t.ai?.reply||t.problem||'')}</div></div></article>`).join(''):x('supportNoTickets')}catch(e){box.innerHTML=`<p class="error">${esc(uiErrorMessage(e))}</p>`}}
function dashboardCard(title,body,route){return `<article class="card"><h3>${title}</h3><p class="muted">${body}</p>${route?routeLink(route,x('open')||x('open'),'button'):''}</article>`}
function readerDashboard(){if(!state.user)return loginGate();return page(x('readerDashboard'),`<div id="readerDash" class="content-grid"><div class="card">${x('final_loading')}</div></div>`)}
function authorDashboard(){if(!state.user)return loginGate();return page(x('authorDashboard'),`<div id="authorDash" class="content-grid"><div class="card">${x('final_loading')}</div></div>`)}
async function loadAdminAuthorityDashboard(){
 const b=document.getElementById('adminAuthorityDash');if(!b)return;
 try{
  const d=await getJSON('/api/admin/authority/overview');
  const modules=(d.modules||[]).map(m=>'<article class="card admin-module-card"><div class="section-heading"><div><span class="eyebrow">'+esc(m.permission)+'</span><h3>'+kvIcon('dashboard')+esc(m.label)+'</h3></div><span class="pill">'+(m.allowed?x('authorized'):x('notAuthorized'))+'</span></div><p class="muted">'+(m.allowed?x('moduleAvailableUnderRights'):x('masterAdminRightNotGranted'))+'</p><button class="button" data-admin-module="'+esc(m.id)+'" data-admin-permission="'+esc(m.permission)+'" data-admin-route="'+esc(m.route)+'">'+x('open')+'</button></article>').join('');
  let master='';
  if(d.role==='master_admin'){
   let requests=[],permissions=[];
   try{requests=(await getJSON('/api/admin/rights-requests')).requests||[]}catch(_){}
   try{permissions=(await getJSON('/api/admin/rbac/permissions')).permissions||[]}catch(_){}
   const permissionRows=permissions.map(r=>'<article class="writing-item"><div><strong>'+esc(r.adminId)+'</strong><div class="muted">'+esc(r.permission)+' · '+(r.active===false?x('disabled'):x('active'))+'</div></div><button class="button '+(r.active===false?'primary':'danger')+'" data-rbac-toggle="1" data-rbac-admin="'+esc(r.adminId)+'" data-rbac-permission="'+esc(r.permission)+'" data-rbac-active="'+(r.active===false?'true':'false')+'">'+(r.active===false?x('enable'):x('disable'))+'</button></article>').join('');
   master='<section class="card"><h2>'+kvIcon('lock')+' '+x('masterAdminAuthorityControl')+'</h2><p class="muted">'+x('ui_human_master_admin_has_full_control_delegated_admin_rights_can_be_expl')+'</p><form id="masterGrantForm"><input id="masterGrantAdminId" placeholder="'+x('adminId')+'" required><input id="masterGrantPermission" placeholder="'+x('permission')+'" required><button class="primary" type="submit">'+x('ui_grant_right')+'</button><div id="masterGrantStatus" class="result"></div></form><h3>'+x('ui_delegated_rights_status')+'</h3><div class="writing-list">'+(permissionRows||'<p class="muted">'+x('ui_no_delegated_rights_recorded')+'</p>')+'</div><h3>'+x('ui_rights_requests')+'</h3><div class="writing-list">'+(requests.map(r=>'<article class="writing-item"><div><strong>'+esc(r.id)+'</strong><div class="muted">'+x('final_admin_request_prefix')+' '+esc(r.ownerId)+' · '+esc(r.status)+'</div><div>'+esc((r.requestedPermissions||[]).join(', '))+'</div></div><div class="button-row"><button class="button" data-rights-approve="'+esc(r.id)+'">'+x('ui_approve')+'</button><button class="button danger" data-rights-reject="'+esc(r.id)+'">'+x('ui_reject')+'</button></div></article>').join('')||'<p class="muted">'+x('ui_no_admin_rights_requests')+'</p>')+'</div></section>';
  }
  b.innerHTML='<section class="card"><h2>'+kvIcon('dashboard')+' '+x('adminAuthorityTitle')+'</h2><p class="muted">'+x('final_role_prefix')+' '+esc(d.role)+' · '+x('final_explicit_rights_master')+'</p><div class="chips">'+((d.rights||[]).map(r=>'<span class="pill">'+esc(r)+'</span>').join('')||'<span class="pill">'+x('ui_no_delegated_rights')+'</span>')+'</div></section>'+master+'<div class="grid">'+modules+'</div><section class="card"><h2>'+kvIcon('ticket')+' '+x('requestAdditionalRights')+'</h2><p class="muted">'+x('ui_submit_a_secure_request_to_master_admin_rights_become_active_only_afte')+'</p><form id="adminRightsRequestForm"><textarea id="adminRightsRequested" rows="4" placeholder="'+x('onePermissionPerLine')+'"></textarea><textarea id="adminRightsReason" rows="3" placeholder="'+x('reason')+'"></textarea><button class="primary" type="submit">'+x('ui_request_rights')+'</button><div id="adminRightsRequestStatus" class="result"></div></form></section>';
  b.querySelectorAll('[data-admin-module]').forEach(btn=>btn.onclick=async()=>{const item=(d.modules||[]).find(x=>x.permission===btn.dataset.adminPermission);if(!item?.allowed){try{await getJSON('/api/admin/authorization/denied-click',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({module:btn.dataset.adminModule,permission:btn.dataset.adminPermission,route:btn.dataset.adminRoute,action:'click'})})}catch(_){}showToast(x('notAuthorizedAskMasterAdmin'),'error');return}navigate(btn.dataset.adminRoute)});
  document.getElementById('adminRightsRequestForm')?.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('adminRightsRequestStatus');const permissions=document.getElementById('adminRightsRequested').value.split(/\n|,/).map(x=>x.trim()).filter(Boolean);try{const r=await getJSON('/api/admin/rights-requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({permissions,reason:document.getElementById('adminRightsReason').value})});status.textContent=x('ui_request')+r.ticket.id+' '+x('submittedToMasterAdmin')}catch(e){status.textContent=uiErrorMessage(e)}});
  document.getElementById('masterGrantForm')?.addEventListener('submit',async e=>{e.preventDefault();const status=document.getElementById('masterGrantStatus');try{const r=await getJSON('/api/admin/rbac/permissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:document.getElementById('masterGrantAdminId').value,permission:document.getElementById('masterGrantPermission').value})});status.textContent=x('ui_granted')+r.permission.permission+' to '+r.permission.adminId;loadAdminAuthorityDashboard()}catch(e){status.textContent=uiErrorMessage(e)}});
  b.querySelectorAll('[data-rbac-toggle]').forEach(btn=>btn.onclick=async()=>{try{await getJSON('/api/admin/rbac/permissions',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:btn.dataset.rbacAdmin,permission:btn.dataset.rbacPermission,active:btn.dataset.rbacActive==='true'})});loadAdminAuthorityDashboard()}catch(e){showToast(uiErrorMessage(e),'error')}});
  b.querySelectorAll('[data-rights-approve]').forEach(btn=>btn.onclick=async()=>{try{await getJSON('/api/admin/rights-requests/'+btn.dataset.rightsApprove,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({approved:true})});loadAdminAuthorityDashboard()}catch(e){showToast(uiErrorMessage(e),'error')}});
  b.querySelectorAll('[data-rights-reject]').forEach(btn=>btn.onclick=async()=>{try{await getJSON('/api/admin/rights-requests/'+btn.dataset.rightsReject,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({approved:false})});loadAdminAuthorityDashboard()}catch(e){showToast(uiErrorMessage(e),'error')}});
 }catch(e){b.innerHTML='<div class="card error">'+esc(uiErrorMessage(e))+'</div>'}
}
