async function loadNotifications(){const box=document.getElementById('notificationCenter');if(!box)return;try{const d=await getJSON('/api/notifications');box.innerHTML=`<div class="notification-toolbar"><strong>${d.unread} ${x('unreadLabel')}</strong><button class="button" id="markAllNotifications">${x('ui_mark_all_read')}</button></div>`+(d.notifications||[]).map(n=>`<article class="notification-item ${n.read?'':'unread'}" data-notification-id="${esc(n.id)}" data-deeplink="${esc(n.deepLink||'')}"><div class="notification-main"><strong>${esc(n.titleKey?x(n.titleKey):n.title)}</strong><p>${esc(n.bodyKey?Object.entries(n.messageParams||{}).reduce((v,[k,val])=>v.replaceAll('{'+k+'}',String(val)),x(n.bodyKey)):n.body)}</p><small>${esc(n.category)} · ${esc(n.createdAt)}</small></div><button class="button notification-open" type="button">${x('open')}</button></article>`).join('')||`<div class="empty card">${x('ui_no_notifications_yet')}</div>`;document.getElementById('markAllNotifications')?.addEventListener('click',async()=>{await getJSON('/api/notifications/read',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({all:true})});loadNotifications()});box.querySelectorAll('.notification-open').forEach(b=>b.onclick=async()=>{const item=b.closest('.notification-item');await getJSON('/api/notifications/read',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:item.dataset.notificationId})});if(item.dataset.deeplink)location.href=item.dataset.deeplink;else loadNotifications()})}catch(e){box.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
async function loadMessages(){const box=document.getElementById('messageList');if(!box)return;try{const d=await getJSON('/api/messages');const groups={};(d.messages||[]).forEach(m=>{const peer=m.from===state.user.id?m.to:m.from;(groups[peer]??=[]).push(m)});box.innerHTML=Object.entries(groups).map(([peer,rows])=>`<article class="card"><h3>${x('ui_conversation')}</h3>${rows.map(m=>`<div class="message-row ${m.from===state.user.id?'sent':'received'}"><div>${esc(m.body)}</div><small>${esc(m.createdAt)}</small>${m.attachment?`<div>📎 ${esc(m.attachment.name||'attachment')}</div>`:''}</div>`).join('')}<button class="button reply-message" data-peer="${esc(peer)}">${x('ui_reply')}</button></article>`).join('')||`<div class="empty card">${x('ui_no_messages_yet')}</div>`;box.querySelectorAll('.reply-message').forEach(b=>b.onclick=()=>composeMessage(b.dataset.peer))}catch(e){box.innerHTML=`<div class="card error">${esc(uiErrorMessage(e))}</div>`}}
async function composeMessage(peer=''){const to=await uiPrompt(x('recipientUserId'));if(!to)return;const body=await uiPrompt(x('messagePrompt'));if(!body)return;try{await getJSON('/api/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({toUserId:to,body})});loadMessages()}catch(e){showToast(uiErrorMessage(e))}}
async function requestInternalPaymentOtp(action,reference,amount){
  const r=await getJSON('/api/payments/internal-otp/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,reference,amount})});
  state.paymentOtpToken=r.paymentToken;state.paymentOtpAction=action;state.paymentOtpReference=reference;
  const m=await openOtpDialog({target:r.target,purpose:r.purpose,targetType:r.targetType,sendPath:'/api/payments/internal-otp/start',sendBody:{action,reference,amount},message:x('paymentVerificationCodeSent').replace('{v1}',r.targetType),lastResponse:r});
  if(!m)throw new Error('payment_otp_cancelled');
  const vr=await getJSON('/api/payments/internal-otp/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paymentToken:state.paymentOtpToken,otp:m.__otp})});
  if(!vr.verified)throw new Error('payment_otp_not_verified');
  return vr.paymentToken;
}
async function loadPaymentPage(){const summary=document.getElementById('paymentPlanSummary'),status=document.getElementById('paymentStatus');if(!summary||!state.user)return;try{const d=await getJSON('/api/monetization/catalog');const plan=(d.policy.subscriptions||[]).find(p=>p.id===state.pendingSubscriptionPlan)||d.policy.subscriptions?.[0];if(!plan){summary.textContent=x('ui_no_active_plan_selected');return}state.pendingSubscriptionPlan=plan.id;let authorLabel='';if(plan.id==='author_subscription'){if(!state.pendingAuthorId){summary.innerHTML='<div class="card error">'+x('ui_choose_an_author_before_checkout')+'</div>';return}try{const ap=await getJSON('/api/profile/public?userId='+encodeURIComponent(state.pendingAuthorId));authorLabel=` · @${esc(ap.profile?.username||state.pendingAuthorId)}`}catch{authorLabel=''}}summary.innerHTML=`<strong>${esc(plan.label)}</strong><span>${esc(plan.type)}${authorLabel} · ${plan.price>0?'₹'+plan.price:x('freeLabel')} · ${plan.durationDays||0} days</span><p class="muted">${plan.adFree?x('adFreeLabel'):x('adsMayApply')} · ${(plan.benefits||[]).map(esc).join(' · ')}</p>`;document.querySelectorAll('[data-payment-method]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-payment-method]').forEach(x=>x.classList.remove('active'));b.classList.add('active')});document.getElementById('confirmPayment')?.addEventListener('click',async()=>{const method=document.querySelector('[data-payment-method].active')?.dataset.paymentMethod||'internal_test';try{status.textContent=x('ui_processing');let paymentToken=null;const idem=`${state.user.id||state.user.username}:${plan.id}:${Date.now()}`;if(method==='internal_test'&&Number(plan.price||0)>0)paymentToken=await requestInternalPaymentOtp('subscription',plan.id==='author_subscription'?`author_subscription:${state.pendingAuthorId}`:plan.id,Number(plan.price||0));const r=await getJSON('/api/subscriptions/purchase',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({planId:plan.id,authorId:plan.id==='author_subscription'?state.pendingAuthorId:undefined,mode:method==='internal_test'?'internal_test':'external',method,idempotencyKey:idem,paymentToken})});status.textContent=r.testMode?x('subscriptionActivatedInternalTest'):x('paymentProviderAccepted');state.user=(await getJSON('/api/auth/me')).user;setTimeout(()=>navigate('account'),500)}catch(e){status.textContent=uiErrorMessage(e)}})}catch(e){summary.textContent=uiErrorMessage(e)}}
async function fileAsDataUrl(input){const f=input?.files?.[0];if(!f)return null;if(f.size>2*1024*1024)throw new Error(x('screenshotTooLarge'));if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw new Error(x('screenshotTypeUnsupported'));return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({mimeType:f.type,data:String(r.result)});r.onerror=()=>reject(new Error(x('screenshotReadFailed')));r.readAsDataURL(f);});}
async function initPublicAiHelp(){const form=document.getElementById('publicAiHelpForm'),out=document.getElementById('publicAiHelpAnswer');if(form&&out)form.onsubmit=async e=>{e.preventDefault();const q=document.getElementById('publicAiHelpQuestion').value.trim();if(!q)return;out.textContent=x('ui_internal_ai_is_checking');try{const r=await getJSON('/api/help/public-ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({problem:q,language:state.uiLanguage})});out.innerHTML=`<strong>${esc(r.ai.reply)}</strong><p class="muted">${esc(r.ai.category)} · ${r.ai.confidence||0}</p>`}catch(err){out.textContent=uiErrorMessage(err)}};const af=document.getElementById('publicAccountStateForm');if(af)af.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('publicAccountStateResult');try{const screenshot=await fileAsDataUrl(document.getElementById('publicAccountStateScreenshot'));const r=await getJSON('/api/help/account-state-ticket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identifier:document.getElementById('publicAccountIdentifier').value,type:document.getElementById('publicAccountStateType').value,reason:document.getElementById('publicAccountStateReason').value,screenshot})});out.innerHTML=`<strong>${x('ui_submitted')}</strong> ${x('ticket')} ${esc(r.ticket?.id||x('created'))}</strong><p class="muted">${x('ui_only_master_admin_can_decide_the_account_state_request')}</p>`}catch(err){out.textContent=uiErrorMessage(err)}};const pf=document.getElementById('publicHelpTicketForm');if(pf)pf.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('publicHelpTicketResult');try{const screenshot=await fileAsDataUrl(document.getElementById('publicHelpTicketScreenshot'));const r=await getJSON('/api/help/public-ticket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identifier:document.getElementById('publicHelpTicketIdentifier').value,problem:document.getElementById('publicHelpTicketProblem').value,channel:'ai',language:state.uiLanguage,screenshot})});out.innerHTML=`<strong>${esc(r.ticket.id)}</strong><p>${esc(r.ticket.status)} · ${esc(r.ticket.problem||'')}</p>`;document.getElementById('publicHelpTicketCommentNumber').value=r.ticket.id;document.getElementById('publicHelpTicketCommentIdentifier').value=document.getElementById('publicHelpTicketIdentifier').value}catch(err){out.textContent=uiErrorMessage(err)}};const pc=document.getElementById('publicHelpTicketCommentForm');if(pc)pc.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('publicHelpTicketCommentResult');try{const r=await getJSON('/api/help/public-ticket',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticketNumber:document.getElementById('publicHelpTicketCommentNumber').value,identifier:document.getElementById('publicHelpTicketCommentIdentifier').value,comment:document.getElementById('publicHelpTicketComment').value})});out.innerHTML=`<strong>${esc(r.ticket.id)}</strong><p>${esc(r.ticket.status)} · ${x('comment')}</p>`;document.getElementById('publicHelpTicketComment').value=''}catch(err){out.textContent=uiErrorMessage(err)}};const tf=document.getElementById('publicTicketTrackForm');if(tf)tf.onsubmit=async e=>{e.preventDefault();const out=document.getElementById('publicTicketTrackResult');try{const n=encodeURIComponent(document.getElementById('publicTicketNumber').value.trim()),i=encodeURIComponent(document.getElementById('publicTicketIdentifier').value.trim());const r=await getJSON(`/api/help/tickets/track?ticketNumber=${n}&identifier=${i}`);out.innerHTML=`<strong>${esc(r.ticket.id)}</strong><p>${esc(r.ticket.status)} · ${esc(r.ticket.problem||'')}</p>`}catch(err){out.textContent=uiErrorMessage(err)}}}
