 document.getElementById('viewerShare')?.addEventListener('click',async()=>{const url=location.href.split('#')[0]+'?work='+encodeURIComponent(c.id);try{if(navigator.share)await navigator.share({title:c.title,url});else{await navigator.clipboard?.writeText(url);showToast(x('linkCopied'))}}catch{}});
