async function probeStudioRuntimeCapabilities(){
 const out={browser:{webgpu:false,webcodecs:false,wasm:false,offscreenCanvas:false,hardwareConcurrency:navigator.hardwareConcurrency||null,deviceMemory:navigator.deviceMemory||null},server:null};
 try{out.browser.wasm=typeof WebAssembly!=='undefined';out.browser.offscreenCanvas=typeof OffscreenCanvas!=='undefined';}catch{}
 try{if(navigator.gpu){const ad=await navigator.gpu.requestAdapter();out.browser.webgpu=!!ad; if(ad&&typeof ad.requestAdapterInfo==='function'){try{const i=await ad.requestAdapterInfo();out.browser.gpuVendor=i.vendor||null;out.browser.gpuArchitecture=i.architecture||null;}catch{}}}}catch{}
 try{if(typeof VideoEncoder!=='undefined'&&typeof VideoEncoder.isConfigSupported==='function'){const r=await VideoEncoder.isConfigSupported({codec:'avc1.640034',width:2160,height:3840,framerate:60,bitrate:42500000});out.browser.webcodecs=!!r.supported;}}catch{}
 try{const r=await getJSON('/api/studio/runtime-capabilities');out.server=r.capabilities||null;}catch(e){out.server={error:e.message};}
 window.kv30StudioRuntime=out;return out;
}


function openCrossFormatTransform(initialType='story'){
 const d=document.createElement('dialog');d.className='kv-smart-dialog';
 d.innerHTML=`<form method="dialog" class="kv-smart-form"><div class="dialog-header"><div><span class="eyebrow">${x('aiCreatorTools')}</span><h2>${kvIcon('globe')} ${x('crossFormat')}</h2></div><button type="button" class="icon-button" data-close>×</button></div><div class="kv-smart-form-grid"><label>${x('sourceFormat')}<select id="xfSource"><option value="story">${x('aiStory')}</option><option value="comic">${x('aiComic')}</option><option value="audio">${x('aiFm')}</option><option value="reel">${x('aiReel')}</option></select></label><label>${x('targetFormat')}<select id="xfTarget"><option value="story">${x('aiStory')}</option><option value="comic">${x('aiComic')}</option><option value="audio">${x('aiFm')}</option><option value="reel">${x('aiReel')}</option></select></label><label>${x('sourceLanguage')}<select id="xfSourceLanguage">${state.languages.map(l=>`<option value="${esc(l.code)}">${esc(l.nativeName||l.name)}</option>`).join('')}</select></label><label>${x('targetLanguage')}<select id="xfTargetLanguage">${state.languages.map(l=>`<option value="${esc(l.code)}">${esc(l.nativeName||l.name)}</option>`).join('')}</select></label></div><textarea id="xfText" rows="7" maxlength="20000" placeholder="${esc(x('currentStoryPremise'))}"></textarea><div class="kv-smart-note">${kvIcon('shield')} ${x('internalAiTransformNote')}</div><div class="dialog-actions"><button type="button" class="button" data-close>${x('cancel')}</button><button type="submit" class="primary">${x('transform')}</button></div><div id="xfResult" class="kv-smart-result" aria-live="polite"></div></form>`;
 document.body.appendChild(d);
 d.querySelector('#xfSource').value=initialType;
 d.querySelector('#xfTarget').value=initialType==='story'?'comic':'story';
 d.querySelector('#xfSourceLanguage').value=state.studioProject?.language||state.uiLanguage||'en';
 d.querySelector('#xfTargetLanguage').value=state.readingLanguage||state.uiLanguage||'en';
 d.querySelector('#xfText').value=document.getElementById('editorBody')?.innerText||document.getElementById('editorTitle')?.value||'';
 const close=()=>{d.close();d.remove()};
 d.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);
 d.querySelector('form').onsubmit=async e=>{
  e.preventDefault();
  const out=d.querySelector('#xfResult');
  const sourceId=document.getElementById('editorForm')?.dataset.id||'';
  const sourceType=d.querySelector('#xfSource').value,targetType=d.querySelector('#xfTarget').value;
  const sourceLanguage=d.querySelector('#xfSourceLanguage').value,targetLanguage=d.querySelector('#xfTargetLanguage').value;
  const sourceText=d.querySelector('#xfText').value.trim();
  if(sourceType===targetType){out.textContent=x('differentTargetFormat');return}
  out.textContent=x('aiBusy');
  try{
   const r=await getJSON('/api/ai/cross-format-transform',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sourceId,sourceText,sourceType,targetType,sourceLanguage,targetLanguage})});
   out.innerHTML=`<strong>${x('proposalReady')}</strong><p>${esc(r.proposal?.text||'')}</p><button type="button" class="primary" id="xfApply">${x('transform')} + ${x('createDraftAction')}</button>`;
   out.querySelector('#xfApply').onclick=async()=>{
    out.textContent=x('aiBusy');
    try{
     const a=await getJSON('/api/ai/cross-format-transform/apply',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sourceId,sourceText,sourceType,targetType,sourceLanguage,targetLanguage,title:document.getElementById('editorTitle')?.value||''})});
     if(a.created){
      out.innerHTML=`<strong>${x('draftCreated')}</strong> ${esc(a.content?.title||'')} · ${esc(a.target?.language||targetLanguage)} · ${x('creatorApprovalRecorded')}`;
      if(a.content?.id)out.innerHTML+=`<br><button type="button" class="button" id="xfOpen">${x('openDraft')}</button>`;
      out.querySelector('#xfOpen')?.addEventListener('click',()=>{close();openEditor(a.content.id)});
     }else out.textContent=x('localModelRequired');
    }catch(err){out.textContent=uiErrorMessage(err)}
   };
  }catch(err){out.textContent=uiErrorMessage(err)}
 };
 d.showModal();
 d.querySelector('#xfText')?.focus();
}
function bindStudioControls(){
 const type=document.getElementById('editorType')?.value||'story';
 document.querySelectorAll('[data-studio-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-studio-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('studioWorkspace')?.scrollIntoView({block:'nearest',behavior:'smooth'})});
 document.getElementById('studioCrossFormat')?.addEventListener('click',()=>openCrossFormatTransform(type));document.getElementById('studioAiVoice')?.addEventListener('click',async()=>{const out=document.getElementById('studioStatus');const text=String(document.getElementById('editorBody')?.innerText||'').trim();if(!text){if(out)out.textContent=x('addTextBeforeAiVoice');return}try{if(out)out.textContent=x('aiBusy');const r=await getJSON('/api/media/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:text.slice(0,2500),languageCode:state.studioProject?.language||state.uiLanguage||'gu-IN',speaker:'shubh',pace:1})});const a=new Audio(r.audioUrl);await a.play();if(out)out.textContent=x('aiVoiceReadyApproval')}catch(e){if(out)out.textContent=uiErrorMessage(e)}});document.getElementById('studioAiPlan')?.addEventListener('click',async()=>{try{const r=await getJSON('/api/ai/creator-studio-plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,title:document.getElementById('editorTitle')?.value||'',prompt:document.getElementById('editorBody')?.innerText||''})});state.studioProject=r.plan||{};renderStudioWorkspace(type,state.studioProject);document.getElementById('studioStatus').textContent=x('aiPlanReadyApproval')}catch(e){document.getElementById('studioStatus').textContent=uiErrorMessage(e)}});
 document.getElementById('studioSave')?.addEventListener('click',async()=>{const f=document.getElementById('editorForm'),cid=f?.dataset.id;if(!cid){document.getElementById('studioStatus').textContent=x('saveDraftBeforeStudio');return}try{const endpoint=type==='story'?'/api/studio/story/'+encodeURIComponent(cid):'/api/content/'+encodeURIComponent(cid)+'/studio';const method=type==='story'?'PUT':'PATCH';await getJSON(endpoint,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify({project:state.studioProject})});document.getElementById('studioStatus').textContent=x('studioProjectSaved')}catch(e){document.getElementById('studioStatus').textContent=uiErrorMessage(e)}});
}
function openPublicProfile(userId){const uid=String(userId||'').trim();if(!uid)return;history.pushState({},'',`/profile?userId=${encodeURIComponent(uid)}`);render('account')}
function speechLocale(code){const m={en:'en-IN',as:'as-IN',bn:'bn-IN',brx:'hi-IN',doi:'hi-IN',gu:'gu-IN',hi:'hi-IN',kn:'kn-IN',ks:'ks-IN',kok:'kok-IN',mai:'mai-IN',ml:'ml-IN',mni:'mni-IN',mr:'mr-IN',ne:'ne-NP',or:'or-IN',pa:'pa-IN',sa:'sa-IN',sat:'sat-IN',sd:'sd-IN',ta:'ta-IN',te:'te-IN',ur:'ur-IN'};return m[String(code||'en').split('-')[0]]||'en-IN'}

